#!/usr/bin/env node
/**
 * API type generator — wraps openapi-typescript.
 *
 * Reads the committed OpenAPI schema snapshot (openapi/schema.json) and
 * writes lib/api/schema.d.ts, following the same pattern as
 * scripts/gen-i18n-types.mjs for message keys.
 *
 * The schema snapshot itself is refreshed separately and explicitly via
 * `npm run api:schema` (see scripts/refresh-api-schema.mjs for the
 * committed-snapshot-vs-live-API decision and its trade-off).
 *
 * Run: npm run api:types
 * Commit the generated file. Re-run whenever openapi/schema.json changes.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const __dirname = dirname(fileURLToPath(import.meta.url));
const webRoot = join(__dirname, "..");
const schemaPath = join(webRoot, "openapi", "schema.json");
const outPath = join(webRoot, "lib", "api", "schema.d.ts");

export const HEADER =
  "// AUTO-GENERATED by scripts/gen-api-types.mjs from openapi/schema.json — do NOT edit manually.\n" +
  "// Re-run `npm run api:types` after refreshing openapi/schema.json (`npm run api:schema`).\n\n";

export async function generate() {
  let schema;
  try {
    schema = JSON.parse(readFileSync(schemaPath, "utf8"));
  } catch (e) {
    console.error(`[api:types] Failed to read ${schemaPath}: ${e.message}`);
    process.exit(1);
  }

  const ast = await openapiTS(schema);
  return HEADER + astToString(ast);
}

async function main() {
  const output = await generate();
  writeFileSync(outPath, output, "utf8");
  console.log(`[api:types] Written TypeScript types to lib/api/schema.d.ts`);
}

// Only run when invoked directly (not when imported by check-api-types.mjs).
if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}
